    pub(super) fn pending_control_wakes(&self) -> Vec<ControlWakeHint> {
        let own = self.account_id();
        let devices = self.linked_devices();
        let state = self.privacy.state.read().expect("privacy state lock");
        let certified = devices
            .iter()
            .filter(|device| {
